    return { stopped: false, stale: false };
  }

  const metadataPid = runtimeMetadata.pid;
  let stale = false;
  let stopped = false;
  try {
    process.kill(metadataPid, 'SIGTERM');
    stopped = await waitForProcessExit(metadataPid);
